(() => {
  const debug = window.SUMO_DEBUG === true || ["localhost", "127.0.0.1"].includes(window.location?.hostname);
  const official = window.SUMO_DATA.banzuke.bashos[0].officialRikishi;
  const parsed = window.SUMO_DATA.rikishi;
  const counts = new Map(parsed.map((person) => [person.id, (parsed.filter((item) => item.id === person.id)).length]));
  for (const person of official) {
    const count = counts.get(person.id) || 0;
    if (debug) console.info(`Rank: ${person.rank}\nSide: ${person.side}\nName: ${person.shikona}\nStatus: Parsed ✓`);
    if (count !== 1) console.error(count ? `WARNING\n\n${person.shikona}\n\nParsed ${count} times; expected exactly once.` : `WARNING\n\n${person.shikona}\n\nNot parsed`);
  }
})();
